/** Every operation this vertical binds to HTTP, one method each. */
export interface DashboardClient {
  /**
   * Suppress with a rule: a scope plus an expiry, audited by the plane
   *
   * `POST /findings/rules` — `dashboard/create-finding-rule`
   */
  createFindingRule(input: { kind?: "invariant" | "drift" | "recurring"; operation?: string; code?: "unauthenticated" | "permission_denied" | "forbidden" | "not_found" | "conflict" | "validation_failed" | "precondition_failed" | "rate_limited" | "unavailable" | "internal"; subject?: string; expiresAt: string; reason: string }): Promise<{ rule: FindingRuleEntry; suppressed: number }>;

  /**
   * This team's suppress rules; `active` keeps the unexpired ones
   *
   * `GET /findings/rules` — `dashboard/list-finding-rules`
   */
  listFindingRules(input: { active?: boolean }): Promise<{ entries: FindingRuleEntry[] }>;

  /**
   * One page of this team's findings, most recently seen first
   *
   * `GET /findings` — `dashboard/list-findings`
   */
  listFindings(input: { status?: "open" | "acked" | "resolved" | "suppressed"; kind?: "invariant" | "drift" | "recurring"; limit?: number; cursor?: string }): Promise<{ available: boolean; entries: FindingEntry[]; nextCursor: string | null }>;

  /**
   * End a suppress rule now
   *
   * `DELETE /findings/rules/{ruleId}` — `dashboard/revoke-finding-rule`
   */
  revokeFindingRule(input: { ruleId: string }): Promise<FindingRuleEntry>;

  /**
   * Acknowledge, resolve or reopen one of this team's findings
   *
   * `PUT /findings/{id}/status` — `dashboard/set-finding-status`
   */
  setFindingStatus(input: { id: string; status: "open" | "acked" | "resolved" }): Promise<FindingEntry>;
}

/**
 * The plumbing below is deliberately untyped against the interface above, and cast
 * once at the end.
 *
 * `send` cannot know an operation's return type — it has a `Response`, not a schema
 * — so every method would otherwise need its own `as` and the file would carry
 * fourteen casts instead of one. The interface is what a caller sees, and it IS
 * derived from the model; this is the seam where a runtime that speaks `unknown`
 * meets it.
 */
type Args = Record<string, unknown>;

const omit = (input: Record<string, unknown>, keys: string[]): Record<string, unknown> => {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(input ?? {})) if (!keys.includes(k)) out[k] = v;
  return out;
};

/** Declared fields become a query string; `undefined` is absent rather than the string "undefined". */
const query = (values: Record<string, unknown> | undefined): string => {
  if (!values) return '';
  const params = new URLSearchParams();
  for (const [k, v] of Object.entries(values)) {
    if (v === undefined || v === null) continue;
    params.set(k, String(v));
  }
  const s = params.toString();
  return s ? `?${s}` : '';
};

export function createClient(options: ClientOptions = {}): DashboardClient {
  const baseUrl = options.baseUrl ?? '/api';
  const doFetch = options.fetch ?? globalThis.fetch.bind(globalThis);
  const readMessage = options.errorMessage ?? defaultErrorMessage;

  /** One request, against a path that is ALREADY prefixed and query-stringed. */
  const raw = async (fullPath: string, method: string, body: unknown): Promise<Response> => {
    const hasBody = body !== undefined && method !== 'GET' && method !== 'DELETE';
    return await doFetch(fullPath, {
      method,
      headers: {
        ...(hasBody ? { 'content-type': 'application/json' } : {}),
        ...(options.headers?.() ?? {}),
      },
      ...(hasBody ? { body: JSON.stringify(body) } : {}),
    });
  };

  const parse = async (res: Response): Promise<unknown> => {
    const text = await res.text();
    const body: unknown = text ? JSON.parse(text) : null;
    if (!res.ok) throw new ApiError(res.status, readMessage(body, res) ?? res.statusText, body);
    return body;
  };

  const send = async (path: string, method: string, body: unknown, params: unknown): Promise<unknown> =>
    await parse(await raw(`${baseUrl}${path}${query(params as Record<string, unknown>)}`, method, body));

  return {
    createFindingRule: (input: Args) =>
      send("/findings/rules", "POST", input, undefined),
    listFindingRules: (input: Args) =>
      send("/findings/rules", "GET", undefined, input),
    listFindings: (input: Args) =>
      send("/findings", "GET", undefined, input),
    revokeFindingRule: (input: Args) =>
      send(`/findings/rules/${encodeURIComponent(String(input.ruleId))}`, "DELETE", undefined, omit(input, ["ruleId"])),
    setFindingStatus: (input: Args) =>
      send(`/findings/${encodeURIComponent(String(input.id))}/status`, "PUT", omit(input, ["id"]), undefined),
  } as unknown as DashboardClient;
}
